"""Unit tests for check_hygiene.py. Run with: python3 -m unittest discover .github/scripts"""

from __future__ import annotations

import sys
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

import check_hygiene as h  # noqa: E402


def text_errors(text: str) -> list[str]:
    errors: list[str] = []
    h.check_text("t", text, errors)
    return errors


def identity_errors(email: str, *, strict: bool, name: str = "Jane Doe") -> list[str]:
    errors: list[str] = []
    h.check_identity("id", name, email, errors, strict=strict)
    return errors


def path_errors(path: str) -> list[str]:
    errors: list[str] = []
    h.check_paths([path], errors)
    return errors


class TextTests(unittest.TestCase):
    def test_clean_text_passes(self) -> None:
        for text in [
            "Add frame header parser",
            "The cursor position is advanced by the frame length.",
            "Replay protection uses a monotonic counter \u2014 see \u00a73.",
            "The Gemini protocol is unrelated.",
        ]:
            self.assertEqual(text_errors(text), [], text)

    def test_ai_notices_fail(self) -> None:
        for text in [
            "\U0001f916 Generated with [Claude Code](https://claude.com/claude-code)",
            "Generated with [Claude Code](https://claude.com/claude-code)",
            "This file was generated by an AI assistant.",
            "Written with ChatGPT",
            "AI-generated test vectors",
            "As an AI, I cannot",
            "Co-Authored-By: Claude <noreply@anthropic.com>",
            "Claude-Session: https://example.invalid/x",
            "Assisted-by: some tool",
            "Uses an LLM to summarize",
            "Tested with opus 4 and gpt-5",
            "Configured via cursor rules",
            "https://chatgpt.com/share/abc",
        ]:
            self.assertNotEqual(text_errors(text), [], text)

    def test_non_english_fails(self) -> None:
        self.assertNotEqual(text_errors("\u041f\u0440\u0438\u0432\u0435\u0442"), [])
        self.assertNotEqual(text_errors("\u4f60\u597d"), [])
        self.assertNotEqual(text_errors("emoji \U0001f600"), [])

    def test_secrets_and_paths_fail(self) -> None:
        for text in [
            "-----BEGIN PRIVATE KEY-----",
            "ghp_" + "a" * 36,
            "AKIA" + "A" * 16,
            "see /home/alice/project/file.rs",
            "see /Users/alice/project",
            "C:\\Users\\alice\\project",
        ]:
            self.assertNotEqual(text_errors(text), [], text)


class IdentityTests(unittest.TestCase):
    MAINTAINER = "88090358+HunterEwok@users.noreply.github.com"

    def test_maintainer_passes_strict(self) -> None:
        self.assertEqual(identity_errors(self.MAINTAINER, strict=True), [])
        self.assertEqual(identity_errors("noreply@github.com", strict=True, name="GitHub"), [])

    def test_external_contributor(self) -> None:
        self.assertEqual(identity_errors("jane@example.org", strict=False), [])
        self.assertNotEqual(identity_errors("jane@example.org", strict=True), [])

    def test_allowed_bots_pass(self) -> None:
        email = "49699333+dependabot[bot]@users.noreply.github.com"
        self.assertEqual(identity_errors(email, strict=True, name="dependabot[bot]"), [])

    def test_ai_identities_fail(self) -> None:
        for email in [
            "noreply@anthropic.com",
            "198982749+Copilot@users.noreply.github.com",
            "cursoragent@cursor.com",
            "1234+some-agent[bot]@users.noreply.github.com",
        ]:
            self.assertNotEqual(identity_errors(email, strict=False), [], email)

    def test_ai_name_fails(self) -> None:
        self.assertNotEqual(identity_errors("x@example.org", strict=False, name="Claude"), [])


class PathTests(unittest.TestCase):
    def test_normalize_keeps_dotfiles(self) -> None:
        self.assertEqual(h.normalize_path("./.github/x.yml"), ".github/x.yml")
        self.assertEqual(h.normalize_path(".gitignore"), ".gitignore")

    def test_regular_paths_pass(self) -> None:
        for path in [".github/workflows/rust.yml", "crates/cpb/src/lib.rs", "docs/agents-overview.md"]:
            self.assertEqual(path_errors(path), [], path)

    def test_tool_files_fail(self) -> None:
        for path in [
            "CLAUDE.md",
            "AGENTS.md",
            ".claude/settings.json",
            "crates/x/.cursor/rules.mdc",
            ".cursorrules",
            ".aider.conf.yml",
            ".github/copilot-instructions.md",
            "docs/\u0442\u0435\u0441\u0442.md",
        ]:
            self.assertNotEqual(path_errors(path), [], path)


if __name__ == "__main__":
    unittest.main()
